import{_ as i,o as e,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Estructura Social y Movilidad de Clases","description":"","frontmatter":{},"headers":[],"relativePath":"es/36-社会结构与阶层流动.md","filePath":"es/36-社会结构与阶层流动.md"}'),n={name:"es/36-社会结构与阶层流动.md"};function d(l,a,t,c,r,u){return e(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="estructura-social-y-movilidad-de-clases" tabindex="-1">Estructura Social y Movilidad de Clases <a class="header-anchor" href="#estructura-social-y-movilidad-de-clases" aria-label="Permalink to &quot;Estructura Social y Movilidad de Clases&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>36</td></tr><tr><td>Módulo</td><td>Tipos de Civilización y Sistemas Sociales</td></tr><tr><td>Palabras clave</td><td>Estructura Social, Movilidad de Clases, Sistema Abierto, Promoción Justa, Anti-Solidificación</td></tr></tbody></table><h2 id="i-conceptos-basicos-de-la-estructura-social-y-la-busqueda-de-la-civilizacion-simbiotica" tabindex="-1">I. Conceptos Básicos de la Estructura Social y la Búsqueda de la Civilización Simbiótica <a class="header-anchor" href="#i-conceptos-basicos-de-la-estructura-social-y-la-busqueda-de-la-civilizacion-simbiotica" aria-label="Permalink to &quot;I. Conceptos Básicos de la Estructura Social y la Búsqueda de la Civilización Simbiótica&quot;">​</a></h2><p>La estructura social se refiere al modo de organización y al patrón de relaciones entre los diferentes grupos de una sociedad, e incluye múltiples dimensiones como la división de clases, la división de roles, la distribución del poder y la asignación de recursos. En cualquier forma de civilización, la estructura social influye profundamente en las oportunidades de desarrollo de los individuos, la eficiencia operativa de la sociedad y la estabilidad a largo plazo de la civilización.</p><p>En la era del Sistema de Cultivo Depredador, la estructura social presentaba una solidificación y desigualdad extremas: existía un abismo infranqueable entre los fuertes y los débiles, el origen determinaba el destino, y las masas de la base casi no tenían posibilidad de movilidad ascendente. Esta estructura social solidificada no solo causó un sufrimiento infinito, sino que también condujo a la pérdida de vitalidad social y al estancamiento de la civilización: el potencial de la gran mayoría de los individuos se desperdiciaba, mientras que unos pocos beneficiarios, para mantener sus privilegios, no dudaban en suprimir la innovación y el progreso.</p><p>Tras el establecimiento de la Civilización Simbiótica del Ancla, la construcción de una estructura social &quot;abierta, móvil, justa y vital&quot; se convirtió en uno de los objetivos centrales. La civilización simbiótica cree firmemente que una estructura social sana debe permitir que cada individuo cambie su destino mediante su propio esfuerzo, debe hacer que los recursos sociales fluyan hacia los más capaces y los que más contribuyen, y debe mantener canales de movilidad fluidos entre las diferentes clases. Solo así se puede estimular plenamente la iniciativa y la creatividad de todos los seres simbióticos y alcanzar el gran objetivo del avance conjunto de las Diez Mil Razas.</p><p>La búsqueda central de la estructura social de la civilización simbiótica puede resumirse en cuatro frases:</p><ol><li><strong>Apertura e inclusión</strong>: la sociedad está abierta a todos los individuos, sin barreras de acceso basadas en la raza, el origen o el género</li><li><strong>Movilidad fluida</strong>: se mantienen canales de movilidad fluidos entre las diferentes clases, y los individuos pueden lograr movilidad ascendente mediante el esfuerzo</li><li><strong>Justicia y equidad</strong>: la asignación de recursos y la provisión de oportunidades siguen el principio de justicia, y cada individuo tiene iguales oportunidades de desarrollo</li><li><strong>Plena vitalidad</strong>: la estructura social es capaz de estimular la iniciativa y la creatividad de los individuos, manteniendo una abundante vitalidad de desarrollo</li></ol><h2 id="ii-la-division-de-clases-sociales-de-la-civilizacion-simbiotica" tabindex="-1">II. La División de Clases Sociales de la Civilización Simbiótica <a class="header-anchor" href="#ii-la-division-de-clases-sociales-de-la-civilizacion-simbiotica" aria-label="Permalink to &quot;II. La División de Clases Sociales de la Civilización Simbiótica&quot;">​</a></h2><p>La división de clases sociales de la civilización simbiótica no toma como criterio el origen, la raza o la riqueza, sino que utiliza el &quot;Índice de Simbiosis&quot; y el &quot;Reino de Cultivo&quot; como referencia central, formando un sistema de clases dinámico y abierto:</p><table tabindex="0"><thead><tr><th>Clase</th><th>Nombre</th><th>Proporción</th><th>Características Centrales</th><th>Responsabilidades Principales</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Líderes Simbióticos</td><td>Aprox. 1%</td><td>Potencias Supremas del Plano, Índice de Simbiosis nivel S, núcleo dirigente de la civilización</td><td>Decisiones estratégicas, mantenimiento de leyes, gobernanza transplanar</td></tr><tr><td>Segundo nivel</td><td>Pilar Simbiótico</td><td>Aprox. 5%</td><td>Cultivadores avanzados, Índice de Simbiosis nivel A, fuerza medular de cada ámbito</td><td>Investigación tecnológica, gestión organizativa, formación de talentos</td></tr><tr><td>Tercer nivel</td><td>Profesionales Simbióticos</td><td>Aprox. 20%</td><td>Cultivadores intermedios, Índice de Simbiosis nivel B, talentos especializados de cada sector</td><td>Servicios especializados, aplicación tecnológica, gestión de base</td></tr><tr><td>Cuarto nivel</td><td>Masa Simbiótica</td><td>Aprox. 60%</td><td>Cultivadores iniciales, Índice de Simbiosis nivel C, fuerza fundacional de la civilización</td><td>Cultivo básico, servicios de producción, participación comunitaria</td></tr><tr><td>Quinto nivel</td><td>Novatos Simbióticos</td><td>Aprox. 14%</td><td>Recién iniciados o en espera de mejora, Índice de Simbiosis nivel D, necesitan ayuda y orientación</td><td>Aprender y crecer, recibir orientación, integración gradual</td></tr></tbody></table><p>Debe enfatizarse especialmente que esta división de clases no es fija e inmutable, sino dinámica y móvil. Cada individuo puede mejorar su Índice de Simbiosis y su Reino de Cultivo mediante el propio esfuerzo, logrando un ascenso de clase; por el contrario, si un individuo no progresa o incluso viola la ética simbiótica, también puede producirse un descenso de clase.</p><p>Además, la división de clases no implica privilegios ni discriminación. Los individuos de cada clase gozan de iguales derechos básicos y de la misma dignidad personal; las diferencias entre clases se reflejan principalmente en la división de responsabilidades y la asignación de recursos, no en la superioridad o inferioridad de la persona.</p><h2 id="iii-mecanismos-y-canales-de-movilidad-de-clases" tabindex="-1">III. Mecanismos y Canales de Movilidad de Clases <a class="header-anchor" href="#iii-mecanismos-y-canales-de-movilidad-de-clases" aria-label="Permalink to &quot;III. Mecanismos y Canales de Movilidad de Clases&quot;">​</a></h2><p>La civilización simbiótica ha establecido un mecanismo de movilidad de clases multicanal y multinivel, garantizando que cada individuo tenga la oportunidad de lograr movilidad ascendente mediante su propio esfuerzo:</p><h3 id="_3-1-canal-de-promocion-por-cultivo" tabindex="-1">3.1 Canal de Promoción por Cultivo <a class="header-anchor" href="#_3-1-canal-de-promocion-por-cultivo" aria-label="Permalink to &quot;3.1 Canal de Promoción por Cultivo&quot;">​</a></h3><p>La promoción por cultivo es el principal canal de movilidad de clases. Mediante la apertura de los Trescientos Sistemas de Cultivo del Origen, la civilización simbiótica ofrece a cada individuo un camino claro de promoción por cultivo:</p><ul><li><strong>Ascenso de reino</strong>: el cultivador eleva su reino mediante el cultivo, de inicial a intermedio, avanzado y supremo; cada ruptura de reino puede traer un ascenso de clase</li><li><strong>Avance de sistema</strong>: el cultivador que logra resultados innovadores en un sistema de cultivo puede obtener un aumento del Índice de Simbiosis y un ascenso de clase</li><li><strong>Innovación tecnológica</strong>: el cultivador que logra innovaciones en tecnología de cultivo o ingeniería puede obtener honores y recompensas de recursos, impulsando su ascenso de clase</li></ul><p>El principio central del canal de promoción por cultivo es &quot;un camino para todos&quot;: sin importar el origen, con un cultivo diligente todos tienen la oportunidad de ascender de clase.</p><h3 id="_3-2-canal-de-promocion-por-contribucion" tabindex="-1">3.2 Canal de Promoción por Contribución <a class="header-anchor" href="#_3-2-canal-de-promocion-por-contribucion" aria-label="Permalink to &quot;3.2 Canal de Promoción por Contribución&quot;">​</a></h3><p>Además del reino de cultivo, la contribución a la civilización simbiótica también es un fundamento importante para la movilidad de clases:</p><ul><li><strong>Contribución al servicio público</strong>: participar en el mantenimiento de anclas, la tutoría, el rescate de emergencia y otros servicios públicos, acumulando valor de contribución</li><li><strong>Contribución a la investigación tecnológica</strong>: realizar contribuciones de investigación en tecnología de cultivo, ingeniería y otros campos</li><li><strong>Contribución a la difusión cultural</strong>: difundir los ideales simbióticos, crear obras culturales, promover el intercambio entre civilizaciones</li><li><strong>Contribución a la participación en la gobernanza</strong>: participar en la gobernanza social, proponer recomendaciones de políticas, impulsar la optimización institucional</li></ul><p>El principio central del canal de promoción por contribución es &quot;más trabajo, más recompensa&quot;: cuanto mayor es la contribución a la civilización simbiótica, mayores son las recompensas y la promoción de clase obtenidas.</p><h3 id="_3-3-canal-de-promocion-por-educacion" tabindex="-1">3.3 Canal de Promoción por Educación <a class="header-anchor" href="#_3-3-canal-de-promocion-por-educacion" aria-label="Permalink to &quot;3.3 Canal de Promoción por Educación&quot;">​</a></h3><p>La educación es una escalera importante para la movilidad de clases. La civilización simbiótica ha establecido un sistema completo de promoción por educación:</p><ul><li><strong>Educación básica</strong>: proporcionar educación de cultivo básico gratuita a cada individuo, garantizando la equidad del punto de partida</li><li><strong>Educación avanzada</strong>: seleccionar mediante exámenes a los mejores alumnos para ingresar en las academias de cultivo avanzado, recibiendo una formación de mayor nivel</li><li><strong>Educación de élite</strong>: seleccionar a los individuos de mayor potencial para el programa de formación de élite, con el apoyo de recursos de primer nivel</li><li><strong>Educación permanente</strong>: ofrecer oportunidades de aprendizaje y mejora continuos a individuos de todas las edades</li></ul><p>El principio central del canal de promoción por educación es la &quot;igualdad de oportunidades&quot;: cada individuo tiene iguales oportunidades de ascender de clase a través de la educación.</p><h3 id="_3-4-canal-de-promocion-especial" tabindex="-1">3.4 Canal de Promoción Especial <a class="header-anchor" href="#_3-4-canal-de-promocion-especial" aria-label="Permalink to &quot;3.4 Canal de Promoción Especial&quot;">​</a></h3><p>Para los individuos que realizan contribuciones destacadas o muestran talentos especiales en campos especiales, la civilización simbiótica dispone de canales de promoción especial:</p><ul><li><strong>Promoción excepcional de talentos especiales</strong>: los individuos con talentos especiales o contribuciones especiales en un campo determinado pueden ascender de clase excepcionalmente</li><li><strong>Promoción por méritos en emergencias</strong>: los individuos que se distinguen al afrontar emergencias (como desastres, invasiones, crisis) pueden obtener una promoción rápida</li><li><strong>Promoción por contribución a la exploración transplanar</strong>: los individuos que realizan contribuciones destacadas en la exploración y arqueología transplanar pueden obtener una promoción</li></ul><h2 id="iv-garantias-institucionales-contra-la-solidificacion-de-clases" tabindex="-1">IV. Garantías Institucionales contra la Solidificación de Clases <a class="header-anchor" href="#iv-garantias-institucionales-contra-la-solidificacion-de-clases" aria-label="Permalink to &quot;IV. Garantías Institucionales contra la Solidificación de Clases&quot;">​</a></h2><p>La fluidez de la movilidad de clases requiere garantías institucionales. La civilización simbiótica ha establecido las siguientes instituciones para prevenir la solidificación de clases:</p><h3 id="_4-1-sistema-antimonopolio" tabindex="-1">4.1 Sistema Antimonopolio <a class="header-anchor" href="#_4-1-sistema-antimonopolio" aria-label="Permalink to &quot;4.1 Sistema Antimonopolio&quot;">​</a></h3><p>La Constitución Simbiótica y la ley antimonopolio prohíben explícitamente que cualquier organización o individuo monopolice los recursos de cultivo, los sistemas de cultivo, las oportunidades educativas, etc. El sistema antimonopolio impide que los grupos de interés establecidos solidifiquen sus privilegios mediante el monopolio de recursos, garantizando la apertura y movilidad de los recursos.</p><h3 id="_4-2-sistema-de-impuesto-sobre-herencias-y-donaciones" tabindex="-1">4.2 Sistema de Impuesto sobre Herencias y Donaciones <a class="header-anchor" href="#_4-2-sistema-de-impuesto-sobre-herencias-y-donaciones" aria-label="Permalink to &quot;4.2 Sistema de Impuesto sobre Herencias y Donaciones&quot;">​</a></h3><p>Para evitar que la riqueza y los recursos solidifiquen las clases a través de la transmisión intergeneracional, la civilización simbiótica aplica un sistema progresivo de impuesto sobre herencias y donaciones. Las herencias y donaciones de alto valor neto deben pagar impuestos a una proporción más alta, que se destinan al fondo común de recursos para el interés colectivo de todos los seres simbióticos.</p><h3 id="_4-3-sistema-de-equidad-educativa" tabindex="-1">4.3 Sistema de Equidad Educativa <a class="header-anchor" href="#_4-3-sistema-de-equidad-educativa" aria-label="Permalink to &quot;4.3 Sistema de Equidad Educativa&quot;">​</a></h3><p>La civilización simbiótica garantiza la equidad educativa a través de la Ley de Garantía Educativa:</p><ul><li>La educación básica es gratuita y abierta a todos los ciudadanos</li><li>La selección para la educación avanzada y la educación de élite se basa en la capacidad y el potencial, sin considerar el origen ni la riqueza</li><li>Se proporciona apoyo y compensación educativa adicional a los grupos desfavorecidos</li><li>Se prohíbe cualquier forma de discriminación y privilegio educativo</li></ul><h3 id="_4-4-sistema-de-monitoreo-de-la-movilidad-de-clases" tabindex="-1">4.4 Sistema de Monitoreo de la Movilidad de Clases <a class="header-anchor" href="#_4-4-sistema-de-monitoreo-de-la-movilidad-de-clases" aria-label="Permalink to &quot;4.4 Sistema de Monitoreo de la Movilidad de Clases&quot;">​</a></h3><p>La red simbiótica verifica y monitorea en tiempo real la situación de la movilidad de clases sociales. Los indicadores centrales de monitoreo incluyen:</p><ul><li><strong>Tasa de movilidad intergeneracional</strong>: el grado de diferencia entre la clase de los hijos y la de los padres</li><li><strong>Tasa de movilidad ascendente</strong>: la proporción de individuos que logran un ascenso de clase en cada período</li><li><strong>Tasa de movilidad descendente</strong>: la proporción de individuos que experimentan un descenso de clase en cada período</li><li><strong>Índice de solidificación de clases</strong>: el grado de &quot;herencia&quot; dentro de cada clase</li></ul><p>Cuando los indicadores de monitoreo muestran que la movilidad de clases se obstruye o aparece una tendencia a la solidificación, las instituciones de gobernanza adoptan ajustes de políticas oportunamente para garantizar la fluidez de la movilidad de clases.</p><h2 id="v-diferencias-en-la-estructura-social-de-los-cinco-tipos-de-civilizacion" tabindex="-1">V. Diferencias en la Estructura Social de los Cinco Tipos de Civilización <a class="header-anchor" href="#v-diferencias-en-la-estructura-social-de-los-cinco-tipos-de-civilizacion" aria-label="Permalink to &quot;V. Diferencias en la Estructura Social de los Cinco Tipos de Civilización&quot;">​</a></h2><p>Los cinco tipos de civilización simbiótica presentan características propias en su estructura social:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Características de Estructura Social</th><th>Particularidades de Movilidad de Clases</th></tr></thead><tbody><tr><td>Tipo Intensivo de Asia Oriental</td><td>Orientado al colectivo, jerarquía clara, basado en familias y sectas</td><td>El canal de movilidad principal es la promoción sectaria, con velocidad media</td></tr><tr><td>Tipo Nórdico de Bienestar</td><td>Aplanado, alta igualdad, clases débiles</td><td>Diferencias de clase pequeñas, poca presión de movilidad, velocidad más lenta</td></tr><tr><td>Tipo Pluralista Norteamericano</td><td>Mercantilizado, pluralista, competencia intensa</td><td>El canal de movilidad principal es la competencia de mercado, rápida pero con grandes diferencias</td></tr><tr><td>Tipo Social Europeo Continental</td><td>Corporativista, codeterminación laboral-capital, democracia deliberativa</td><td>La movilidad se basa principalmente en cualificaciones profesionales y negociación colectiva, estable</td></tr><tr><td>Tipo de Desarrollo y Alcance</td><td>Gobierno fuerte, movilidad rápida, desarrollo escalonado</td><td>Movilidad rápida, muchas oportunidades de ascenso, gran vitalidad social</td></tr></tbody></table><p>Aunque la estructura social de cada tipo presenta diferencias, todos siguen los principios básicos de la Constitución Simbiótica y todos se dedican a construir una estructura social abierta, móvil, justa y vital.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La estructura social y la movilidad de clases son uno de los temas centrales de la construcción institucional de la Civilización Simbiótica del Ancla. Mediante la división dinámica de clases centrada en el Índice de Simbiosis y el Reino de Cultivo, los mecanismos de movilidad de clases multicanal y las garantías institucionales contra la solidificación de clases, la civilización simbiótica ha construido una estructura social abierta, móvil, justa y vital. En esta estructura social, cada individuo puede cambiar su destino mediante su propio esfuerzo, los recursos sociales fluyen hacia los más capaces y los que más contribuyen, y toda la civilización mantiene una abundante vitalidad de desarrollo. Esta es la importante base social sobre la cual la civilización simbiótica puede realizar el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (Principio del Equilibrio entre Individuo y Colectivo)</li><li>29-共生度评估体系 (Sistema de Evaluación del Índice de Simbiosis)</li><li>30-五种共生文明分型总览 (Panorama General de los Cinco Tipos de Civilización Simbiótica)</li></ul>',51)])])}const v=i(n,[["render",d]]);export{m as __pageData,v as default};
